{{ (function (rows) {
  var esc = function (s) {
    return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  };
  var siisti = function (t) {
    return String(t == null ? '' : t)
      .replace(/\r\n/g, '\n')
      .replace(/([^\s<]+)<mailto:[^>]*>/gi, '$1')
      .replace(/([^\s<]+)<https?:\/\/[^>]*>/gi, '$1')
      .replace(/\[cid:[^\]]+\]/gi, '[kuva viestissa]')
      .replace(/^[ \t]*\*[ \t]*\n/gm, '• ')
      .replace(/\n{3,}/g, '\n\n');
  };
  var LAINAUS = [
    /^>/,
    /^_{10,}\s*$/,
    /^-{2,}\s*(Alkuper[äa]inen viesti|Original Message)\s*-{2,}/i,
    /^(L[äa]hett[äa]j[äa]|From)\s*:\s*\S/i,
    /^(L[äa]hetetty|Sent)\s*:\s*\S/i,
    /^On .+ wrote:\s*$/i,
    /.{0,160}\bkirjoitti:\s*$/i,
    /reacted to your message:\s*$/i
  ];
  var jaa = function (teksti) {
    var rivit = teksti.split('\n');
    var k = -1;
    for (var i = 1; i < rivit.length; i++) {
      for (var j = 0; j < LAINAUS.length; j++) { if (LAINAUS[j].test(rivit[i])) { k = i; break; } }
      if (k >= 0) break;
    }
    var nakyva = teksti, piilo = '';
    if (k > 0) {
      var alku = rivit.slice(0, k).join('\n').replace(/\s+$/, '');
      if (alku.replace(/\s/g, '').length >= 20) {
        nakyva = alku;
        piilo = rivit.slice(k).join('\n').replace(/^\s+/, '');
      }
    }
    if (nakyva.length > 1200) {
      var leikkaus = nakyva.lastIndexOf('\n', 1200);
      if (leikkaus < 400) leikkaus = 1200;
      piilo = nakyva.slice(leikkaus).replace(/^\s+/, '') + (piilo ? '\n\n' + piilo : '');
      nakyva = nakyva.slice(0, leikkaus);
    }
    return [nakyva, piilo];
  };
  var pvm = function (v) {
    var d = new Date(v);
    if (!v || isNaN(d.getTime())) return '';
    var p = function (n) { return n < 10 ? '0' + n : '' + n; };
    return d.getDate() + '.' + (d.getMonth() + 1) + '.' + d.getFullYear() + ' klo ' + p(d.getHours()) + '.' + p(d.getMinutes());
  };
  var kuka = function (osoite, lahteva) {
    var a = String(osoite || '').trim();
    if (!a) return lahteva ? 'Nokian Kilpipaino' : 'Tuntematon lähettäjä';
    if (!lahteva) return a;
    var m = a.match(/<([^>]+)>/);
    var em = m ? m[1] : a;
    var etu = em.split('@')[0];
    return (etu ? etu.charAt(0).toUpperCase() + etu.slice(1) : 'Me') + ' · ' + em;
  };
  var lista = (rows || []).slice().sort(function (a, b) {
    return new Date(a.sent_at || a.created_at || 0) - new Date(b.sent_at || b.created_at || 0);
  });
  var css = '<meta charset="utf-8"><style>' +
    'html,body{height:100%;margin:0}' + '.wrap{height:100%;box-sizing:border-box;padding:4px 4px 8px;overflow-y:auto;display:flex;flex-direction:column-reverse}' + '.wrap>.m:first-child{margin-bottom:auto}' +
    'body{margin:0;height:100%;' +
    'font:13.5px/1.55 -apple-system,Segoe UI,Roboto,Arial,sans-serif;color:#1f2328;background:#fff}' +
    '.m{flex:0 0 auto;border:1px solid #e1e4e8;border-radius:8px;margin:5px 0;overflow:hidden}' +
    '.m.out{border-color:#c7d9f2}' +
    '.h{display:flex;justify-content:space-between;align-items:baseline;gap:10px;padding:7px 11px;background:#f4f5f7;border-bottom:1px solid #e1e4e8;font-size:12px}' +
    '.m.out .h{background:#eaf1fb}' +
    '.who{font-weight:600;color:#24292f;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}' +
    '.oik{white-space:nowrap;color:#57606a}' +
    '.tag{display:inline-block;font-size:10.5px;font-weight:600;letter-spacing:.03em;text-transform:uppercase;padding:1px 6px;border-radius:9px;background:#dde1e6;color:#424a53;margin-right:6px}' +
    '.m.out .tag{background:#2f6fd0;color:#fff}' +
    '.b{padding:10px 12px;white-space:pre-wrap;overflow-wrap:anywhere}' +
    'details{margin-top:6px}' +
    'summary{cursor:pointer;color:#2f6fd0;font-size:12px;list-style:none}' +
    'summary::-webkit-details-marker{display:none}' +
    'summary:before{content:"\\00b7\\00b7\\00b7";display:inline-block;background:#e7eaee;border-radius:8px;padding:0 7px;margin-right:6px;color:#57606a;line-height:1.1}' +
    '.q{white-space:pre-wrap;overflow-wrap:anywhere;color:#6a737d;border-left:3px solid #e1e4e8;padding-left:10px;margin-top:8px;font-size:12.5px}' +
    '.tyhja{color:#6a737d;padding:18px;text-align:center;font-style:italic}' +
    '</style>';
  if (!lista.length) return css + '<div class="tyhja">Ei viesteja tassa ketjussa.</div>';
  var html = '';
  for (var i = lista.length - 1; i >= 0; i--) {
    var v = lista[i];
    var out = String(v.suunta) === 'lahteva';
    var osat = jaa(siisti(v.body_text));
    html += '<div class="m ' + (out ? 'out' : 'in') + '">' +
      '<div class="h"><span class="who">' + esc(kuka(v.lahettaja, out)) + '</span>' +
      '<span class="oik"><span class="tag">' + (out ? 'Vastattu' : 'Saapunut') + '</span>' +
      esc(pvm(v.sent_at || v.created_at)) + '</span></div>' +
      '<div class="b">' + esc(osat[0]) +
      (osat[1] ? '<details><summary>Näytä loput</summary><div class="q">' + esc(osat[1]) + '</div></details>' : '') +
      '</div></div>';
  }
  return css + '<div class="wrap">' + html + '</div>';
})(getViestitTk.data) }}
